begin;
create function pg_temp.assert_true(value boolean,message text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'money assertion: %',message;end if;end;$$;
create function pg_temp.expect_failure(query text,message text) returns void language plpgsql as $$begin begin execute query;exception when others then if position(message in sqlerrm)>0 then return;end if;raise;end;raise exception 'expected %',message;end;$$;
